    #[test]
    fn push_line_preserves_3x3_query_order_and_duplicates() {
        let mut grid = FlatIntMap::default();
        let cell0 = (-1, -1);
        let cell1 = (-1, 0);
        push_line(&mut grid, &test_line(20), &[cell0]);
        push_line(&mut grid, &test_line(10), &[cell1]);
